#!/usr/bin/env python3
"""
Validation script for pipeline outputs.

Validates the following output files:
- outputs/t01_selected_indicators.csv
- outputs/t05_clean_stops.csv
- outputs/t08_pois_clean.csv
- outputs/t10_accessibility_scores.csv
- outputs/t13_city_clusters.csv

Outputs: outputs/t14_validation_summary.json
"""

import csv
import json
import os
import sys

# Paths to validate
OUTPUT_FILES = [
    "outputs/t01_selected_indicators.csv",
    "outputs/t05_clean_stops.csv",
    "outputs/t08_pois_clean.csv",
    "outputs/t10_accessibility_scores.csv",
    "outputs/t13_city_clusters.csv",
]

def check_file_exists(path):
    """Check if a file exists."""
    return os.path.exists(path)

def check_file_not_empty(path):
    """Check if a file is not empty."""
    if not os.path.exists(path):
        return False, "File does not exist"
    size = os.path.getsize(path)
    if size == 0:
        return False, "File is empty"
    return True, f"File exists and has {size} bytes"

def check_csv_has_header(path):
    """Check if CSV file has a header row."""
    if not os.path.exists(path):
        return False, "File does not exist"
    try:
        with open(path, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                return False, "File has no header row"
            if len(header) == 0:
                return False, "Header row is empty"
            return True, f"File has header with {len(header)} columns: {header[:3]}..." if len(header) > 3 else f"File has header: {header}"
    except csv.Error as e:
        return False, f"Error reading CSV: {str(e)}"

def check_csv_has_required_columns(path, required_columns):
    """Check if CSV file contains all required columns."""
    if not os.path.exists(path):
        return False, "File does not exist"
    try:
        with open(path, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            fieldnames = reader.fieldnames
            if fieldnames is None:
                return False, "No fieldnames found in CSV"
            missing = [col for col in required_columns if col not in fieldnames]
            if missing:
                return False, f"Missing required columns: {missing}"
            return True, f"All required columns present: {', '.join(required_columns)}"
    except csv.Error as e:
        return False, f"Error reading CSV: {str(e)}"

def check_csv_row_count(path, min_rows=None):
    """Check if CSV file has at least min_rows rows (excluding header)."""
    if not os.path.exists(path):
        return False, "File does not exist"
    try:
        with open(path, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            next(reader, None)  # Skip header
            rows = list(reader)
            if min_rows is not None and len(rows) < min_rows:
                return False, f"Only {len(rows)} rows found, minimum is {min_rows}"
            return True, f"File has {len(rows)} data rows"
    except csv.Error as e:
        return False, f"Error reading CSV: {str(e)}"

def check_csv_valid_data_types(path):
    """Check if CSV file has valid data in numeric columns."""
    if not os.path.exists(path):
        return False, "File does not exist"
    try:
        with open(path, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            fieldnames = reader.fieldnames
            if fieldnames is None:
                return False, "No fieldnames found"
            # Check numeric columns
            numeric_columns = [col for col in fieldnames if col in ['latitude', 'longitude', 'distance_m', 'accessibility_score', 'stop_lat', 'stop_lon', 'year', 'cluster_id']]
            if numeric_columns:
                has_valid_data = True
                for row_num, row in enumerate(reader, 1):
                    for col in numeric_columns:
                        if col in row and row[col]:
                            try:
                                float(row[col])
                            except (ValueError, TypeError):
                                has_valid_data = False
                                break
                    if not has_valid_data:
                        break
                if not has_valid_data:
                    return False, "Found invalid numeric data in columns: " + ", ".join(numeric_columns)
            return True, "Numeric data columns are valid"
    except csv.Error as e:
        return False, f"Error reading CSV: {str(e)}"

def check_data_consistency(path, other_path, common_columns=None):
    """Check data consistency between two CSV files."""
    if not os.path.exists(path) or not os.path.exists(other_path):
        return False, "One or both files do not exist"
    try:
        with open(path, 'r', encoding='utf-8') as f1, open(other_path, 'r', encoding='utf-8') as f2:
            reader1 = csv.DictReader(f1)
            reader2 = csv.DictReader(f2)
            fieldnames1 = reader1.fieldnames
            fieldnames2 = reader2.fieldnames
            if fieldnames1 is None or fieldnames2 is None:
                return False, "One or both files have no fieldnames"
            if common_columns:
                missing_in_1 = [col for col in common_columns if col not in fieldnames1]
                missing_in_2 = [col for col in common_columns if col not in fieldnames2]
                if missing_in_1 or missing_in_2:
                    return False, f"Missing common columns: {missing_in_1 + missing_in_2}"
            return True, "Data consistency check passed"
    except csv.Error as e:
        return False, f"Error reading CSV: {str(e)}"

def get_file_stats(path):
    """Get file statistics."""
    if not os.path.exists(path):
        return None
    size = os.path.getsize(path)
    with open(path, 'r', encoding='utf-8') as f:
        lines = f.readlines()
    return {"size_bytes": size, "line_count": len(lines)}

def run_checks():
    """Run all validation checks and return results."""
    results = []

    # Check 1: t01_selected_indicators.csv exists and is not empty
    path = "outputs/t01_selected_indicators.csv"
    exists, msg = check_file_exists(path)
    passed = exists
    results.append({
        "check_name": "t01_file_exists",
        "passed": passed,
        "message": msg
    })

    # Check 2: t01_selected_indicators.csv has required columns
    if passed:
        required_cols_t01 = ['indicator_id', 'indicator_name', 'theme']
        has_cols, msg = check_csv_has_required_columns(path, required_cols_t01)
        results.append({
            "check_name": "t01_has_required_columns",
            "passed": has_cols,
            "message": msg
        })
    else:
        results.append({
            "check_name": "t01_has_required_columns",
            "passed": False,
            "message": "Cannot check columns: file does not exist"
        })

    # Check 3: t05_clean_stops.csv exists and is not empty
    path = "outputs/t05_clean_stops.csv"
    exists, msg = check_file_exists(path)
    passed = exists
    results.append({
        "check_name": "t05_file_exists",
        "passed": passed,
        "message": msg
    })

    # Check 4: t05_clean_stops.csv has required columns
    if passed:
        required_cols_t05 = ['stop_id', 'stop_name', 'stop_lat', 'stop_lon']
        has_cols, msg = check_csv_has_required_columns(path, required_cols_t05)
        results.append({
            "check_name": "t05_has_required_columns",
            "passed": has_cols,
            "message": msg
        })
    else:
        results.append({
            "check_name": "t05_has_required_columns",
            "passed": False,
            "message": "Cannot check columns: file does not exist"
        })

    # Check 5: t05_clean_stops.csv has minimum row count
    if passed:
        row_count, msg = check_csv_row_count(path, min_rows=1)
        results.append({
            "check_name": "t05_minimum_rows",
            "passed": row_count,
            "message": msg
        })
    else:
        results.append({
            "check_name": "t05_minimum_rows",
            "passed": False,
            "message": "Cannot check row count: file does not exist"
        })

    # Check 6: t08_pois_clean.csv exists and is not empty
    path = "outputs/t08_pois_clean.csv"
    exists, msg = check_file_exists(path)
    passed = exists
    results.append({
        "check_name": "t08_file_exists",
        "passed": passed,
        "message": msg
    })

    # Check 7: t08_pois_clean.csv has required columns
    if passed:
        required_cols_t08 = ['qid', 'label', 'poi_type', 'latitude', 'longitude']
        has_cols, msg = check_csv_has_required_columns(path, required_cols_t08)
        results.append({
            "check_name": "t08_has_required_columns",
            "passed": has_cols,
            "message": msg
        })
    else:
        results.append({
            "check_name": "t08_has_required_columns",
            "passed": False,
            "message": "Cannot check columns: file does not exist"
        })

    # Check 8: t10_accessibility_scores.csv exists and is not empty
    path = "outputs/t10_accessibility_scores.csv"
    exists, msg = check_file_exists(path)
    passed = exists
    results.append({
        "check_name": "t10_file_exists",
        "passed": passed,
        "message": msg
    })

    # Check 9: t10_accessibility_scores.csv has required columns
    if passed:
        required_cols_t10 = ['qid', 'label', 'poi_type', 'distance_m', 'accessibility_score']
        has_cols, msg = check_csv_has_required_columns(path, required_cols_t10)
        results.append({
            "check_name": "t10_has_required_columns",
            "passed": has_cols,
            "message": msg
        })
    else:
        results.append({
            "check_name": "t10_has_required_columns",
            "passed": False,
            "message": "Cannot check columns: file does not exist"
        })

    # Check 10: t10_accessibility_scores.csv has valid numeric data
    if passed:
        valid_data, msg = check_csv_valid_data_types(path)
        results.append({
            "check_name": "t10_valid_numeric_data",
            "passed": valid_data,
            "message": msg
        })
    else:
        results.append({
            "check_name": "t10_valid_numeric_data",
            "passed": False,
            "message": "Cannot check numeric data: file does not exist"
        })

    # Check 11: t13_city_clusters.csv exists and is not empty
    path = "outputs/t13_city_clusters.csv"
    exists, msg = check_file_exists(path)
    passed = exists
    results.append({
        "check_name": "t13_file_exists",
        "passed": passed,
        "message": msg
    })

    # Check 12: t13_city_clusters.csv has required columns
    if passed:
        required_cols_t13 = ['city_id', 'city_name', 'year', 'cluster_id']
        has_cols, msg = check_csv_has_required_columns(path, required_cols_t13)
        results.append({
            "check_name": "t13_has_required_columns",
            "passed": has_cols,
            "message": msg
        })
    else:
        results.append({
            "check_name": "t13_has_required_columns",
            "passed": False,
            "message": "Cannot check columns: file does not exist"
        })

    # Check 13: t13_city_clusters.csv has minimum row count
    if passed:
        row_count, msg = check_csv_row_count(path, min_rows=1)
        results.append({
            "check_name": "t13_minimum_rows",
            "passed": row_count,
            "message": msg
        })
    else:
        results.append({
            "check_name": "t13_minimum_rows",
            "passed": False,
            "message": "Cannot check row count: file does not exist"
        })

    return results

def main():
    """Main function to run validation and write results."""
    print("Starting validation of pipeline outputs...")

    results = run_checks()

    # Determine overall status
    all_passed = all(entry["passed"] for entry in results)

    # Write results to JSON file
    output_path = "outputs/t14_validation_summary.json"
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(results, f, indent=2, ensure_ascii=False)

    print(f"Validation complete. Results written to {output_path}")
    print(f"Overall status: {'PASSED' if all_passed else 'FAILED'}")

    # Print summary
    passed_count = sum(1 for entry in results if entry["passed"])
    failed_count = len(results) - passed_count
    print(f"Checks passed: {passed_count}/{len(results)}")

    if not all_passed:
        print("\nFailed checks:")
        for entry in results:
            if not entry["passed"]:
                print(f"  - {entry['check_name']}: {entry['message']}")

    return 0 if all_passed else 1

if __name__ == "__main__":
    sys.exit(main())

